// Probe harness: run the reference executable, extract the r4 values_changed line,
// pull out the 'diff' repr and unescape it back to real text.
import { execFileSync } from 'node:child_process';

const EXE = '/workspace/dataset/test11_executable';

export function run(a, b = '1') {
  const out = execFileSync(EXE, ['--a', a, '--b', String(b)], { encoding: 'utf8' });
  return out;
}

export function r4line(a, b = '1') {
  const out = run(a, b);
  const lines = out.split('\n');
  for (const L of lines) if (L.startsWith("{'values_changed'")) return L;
  return null;
}

// Extract the raw repr body of the 'diff' key (assumes no quote chars in payload).
export function diffRepr(a, b = '1') {
  const L = r4line(a, b);
  if (L === null) return { present: false, raw: null, text: null, line: null };
  const m = L.match(/'diff': '((?:[^'\\]|\\.)*)'/);
  if (!m) return { present: false, raw: null, text: null, line: L };
  const raw = m[1];
  const text = raw
    .replace(/\\x([0-9a-fA-F]{2})/g, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/\\u([0-9a-fA-F]{4})/g, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '\r')
    .replace(/\\t/g, '\t')
    .replace(/\\v/g, '\v')
    .replace(/\\f/g, '\f')
    .replace(/\\'/g, "'")
    .replace(/\\\\/g, '\\');
  return { present: true, raw, text, line: L };
}

if (process.argv[1] && process.argv[1].endsWith('probe.mjs')) {
  const a = process.argv[2];
  const b = process.argv[3] ?? '1';
  const r = diffRepr(a, b);
  console.log('PRESENT:', r.present);
  if (r.present) {
    console.log('RAW:', r.raw);
    console.log('---- rendered ----');
    console.log(r.text);
    console.log('---- end ----');
  } else {
    console.log('LINE:', r.line);
  }
}

