// difflib probe: run the reference executable, extract the r4 values_changed line,
// pull out the 'diff' repr and unescape it back to real text.
// Test scaffolding only - never shipped.
import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test11_executable';

export function run(a, b = '1') {
  const r = spawnSync(EXE, ['--a', a, '--b', String(b)], {
    encoding: 'buffer',
    maxBuffer: 1 << 28,
  });
  return { out: (r.stdout ?? Buffer.alloc(0)).toString('utf8'), code: r.status };
}

export function r4line(a, b = '1') {
  const { out } = run(a, b);
  for (const L of out.split('\n')) if (L.startsWith("{'values_changed'")) return L;
  return null;
}

function unesc(raw) {
  let s = '';
  for (let i = 0; i < raw.length; i++) {
    const c = raw[i];
    if (c !== '\\') { s += c; continue; }
    const n = raw[++i];
    if (n === 'n') s += '\n';
    else if (n === 'r') s += '\r';
    else if (n === 't') s += '\t';
    else if (n === 'v') s += '\v';
    else if (n === 'f') s += '\f';
    else if (n === 'x') { s += String.fromCharCode(parseInt(raw.slice(i + 1, i + 3), 16)); i += 2; }
    else if (n === 'u') { s += String.fromCharCode(parseInt(raw.slice(i + 1, i + 5), 16)); i += 4; }
    else s += n;
  }
  return s;
}

// Extract the repr body of the 'diff' key. Payload must not contain quote chars.
export function diffOf(a, b = '1') {
  const L = r4line(a, b);
  if (L === null) return { present: false, raw: null, text: null, line: null };
  const m = L.match(/'diff': '((?:[^'\\]|\\.)*)'/);
  if (!m) return { present: false, raw: null, text: null, line: L };
  return { present: true, raw: m[1], text: unesc(m[1]), line: L };
}

if (process.argv[1] && process.argv[1].endsWith('diffprobe.mjs')) {
  // argv[2] is a JS-escaped string (JSON) so control chars are easy to pass
  const a = JSON.parse(process.argv[2]);
  const b = process.argv[3] ?? '1';
  const r = diffOf(a, b);
  console.log('input   :', JSON.stringify(a).slice(0, 200));
  console.log('present :', r.present);
  if (r.present) console.log('diff    :', JSON.stringify(r.text));
  else console.log('r4 line :', r.line);
}

// Faithful JS port of CPython difflib.SequenceMatcher + unified_diff + str.splitlines.
// SCAFFOLDING ONLY (/workspace/verify) - used to validate the spec against the executable.

// ---------------------------------------------------------------- splitlines
const BOUNDARY = new Set([
  0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x85, 0x2028, 0x2029,
]);

export function splitlines(s) {
  const out = [];
  let start = 0;
  let i = 0;
  const n = s.length;
  while (i < n) {
    const c = s.codePointAt(i);
    if (BOUNDARY.has(c)) {
      let end = i;
      let next = i + 1;
      if (c === 0x0d && next < n && s.charCodeAt(next) === 0x0a) next++;
      out.push(s.slice(start, end));
      start = next;
      i = next;
    } else {
      i += c > 0xffff ? 2 : 1;
    }
  }
  if (start < n) out.push(s.slice(start));
  return out;
}

// ------------------------------------------------------- SequenceMatcher
export class SequenceMatcher {
  constructor(isjunk, a, b, autojunk = true) {
    this.isjunk = isjunk ?? null;
    this.autojunk = autojunk;
    this.a = a;
    this.b = b;
    this.matchingBlocks = null;
    this.opcodes = null;
    this.#chainB();
  }

  #chainB() {
    const b = this.b;
    const b2j = new Map();
    for (let i = 0; i < b.length; i++) {
      let idx = b2j.get(b[i]);
      if (idx === undefined) { idx = []; b2j.set(b[i], idx); }
      idx.push(i);
    }
    this.b2j = b2j;

    const junk = new Set();
    this.bjunk = junk;
    if (this.isjunk) {
      for (const elt of b2j.keys()) if (this.isjunk(elt)) junk.add(elt);
      for (const elt of junk) b2j.delete(elt);
    }

    const popular = new Set();
    this.bpopular = popular;
    const n = b.length;
    if (this.autojunk && n >= 200) {
      const ntest = Math.floor(n / 100) + 1;
      for (const [elt, idxs] of b2j) if (idxs.length > ntest) popular.add(elt);
      for (const elt of popular) b2j.delete(elt);
    }
  }

  findLongestMatch(alo, ahi, blo, bhi) {
    const { a, b, b2j, bjunk } = this;
    let besti = alo, bestj = blo, bestsize = 0;
    let j2len = new Map();
    for (let i = alo; i < ahi; i++) {
      const newj2len = new Map();
      const js = b2j.get(a[i]);
      if (js) {
        for (const j of js) {
          if (j < blo) continue;
          if (j >= bhi) break;
          const k = (j2len.get(j - 1) ?? 0) + 1;
          newj2len.set(j, k);
          if (k > bestsize) { besti = i - k + 1; bestj = j - k + 1; bestsize = k; }
        }
      }
      j2len = newj2len;
    }
    while (besti > alo && bestj > blo && !bjunk.has(b[bestj - 1]) &&
           a[besti - 1] === b[bestj - 1]) { besti--; bestj--; bestsize++; }
    while (besti + bestsize < ahi && bestj + bestsize < bhi &&
           !bjunk.has(b[bestj + bestsize]) &&
           a[besti + bestsize] === b[bestj + bestsize]) bestsize++;
    while (besti > alo && bestj > blo && bjunk.has(b[bestj - 1]) &&
           a[besti - 1] === b[bestj - 1]) { besti--; bestj--; bestsize++; }
    while (besti + bestsize < ahi && bestj + bestsize < bhi &&
           bjunk.has(b[bestj + bestsize]) &&
           a[besti + bestsize] === b[bestj + bestsize]) bestsize++;
    return [besti, bestj, bestsize];
  }

  getMatchingBlocks() {
    if (this.matchingBlocks) return this.matchingBlocks;
    const la = this.a.length, lb = this.b.length;
    const queue = [[0, la, 0, lb]];
    const blocks = [];
    while (queue.length) {
      const [alo, ahi, blo, bhi] = queue.pop();
      const m = this.findLongestMatch(alo, ahi, blo, bhi);
      const [i, j, k] = m;
      if (k) {
        blocks.push(m);
        if (alo < i && blo < j) queue.push([alo, i, blo, j]);
        if (i + k < ahi && j + k < bhi) queue.push([i + k, ahi, j + k, bhi]);
      }
    }
    blocks.sort((x, y) => x[0] - y[0] || x[1] - y[1] || x[2] - y[2]);

    let i1 = 0, j1 = 0, k1 = 0;
    const nonAdjacent = [];
    for (const [i2, j2, k2] of blocks) {
      if (i1 + k1 === i2 && j1 + k1 === j2) k1 += k2;
      else {
        if (k1) nonAdjacent.push([i1, j1, k1]);
        i1 = i2; j1 = j2; k1 = k2;
      }
    }
    if (k1) nonAdjacent.push([i1, j1, k1]);
    nonAdjacent.push([la, lb, 0]);
    this.matchingBlocks = nonAdjacent;
    return nonAdjacent;
  }

  getOpcodes() {
    if (this.opcodes) return this.opcodes;
    let i = 0, j = 0;
    const answer = [];
    for (const [ai, bj, size] of this.getMatchingBlocks()) {
      let tag = '';
      if (i < ai && j < bj) tag = 'replace';
      else if (i < ai) tag = 'delete';
      else if (j < bj) tag = 'insert';
      if (tag) answer.push([tag, i, ai, j, bj]);
      i = ai + size; j = bj + size;
      if (size) answer.push(['equal', ai, i, bj, j]);
    }
    this.opcodes = answer;
    return answer;
  }

  *getGroupedOpcodes(n = 3) {
    let codes = this.getOpcodes();
    if (!codes.length) codes = [['equal', 0, 1, 0, 1]];
    codes = codes.map((c) => c.slice());
    if (codes[0][0] === 'equal') {
      const [tag, ii1, ii2, jj1, jj2] = codes[0];
      codes[0] = [tag, Math.max(ii1, ii2 - n), ii2, Math.max(jj1, jj2 - n), jj2];
    }
    const last = codes.length - 1;
    if (codes[last][0] === 'equal') {
      const [tag, ii1, ii2, jj1, jj2] = codes[last];
      codes[last] = [tag, ii1, Math.min(ii2, ii1 + n), jj1, Math.min(jj2, jj1 + n)];
    }
    const nn = n + n;
    let group = [];
    for (const code of codes) {
      let [tag, i1, i2, j1, j2] = code;
      if (tag === 'equal' && i2 - i1 > nn) {
        group.push([tag, i1, Math.min(i2, i1 + n), j1, Math.min(j2, j1 + n)]);
        yield group;
        group = [];
        i1 = Math.max(i1, i2 - n);
        j1 = Math.max(j1, j2 - n);
      }
      group.push([tag, i1, i2, j1, j2]);
    }
    if (group.length && !(group.length === 1 && group[0][0] === 'equal')) yield group;
  }
}

// ------------------------------------------------------------ unified_diff
function formatRangeUnified(start, stop) {
  let beginning = start + 1;
  const length = stop - start;
  if (length === 1) return String(beginning);
  if (!length) beginning -= 1;
  return `${beginning},${length}`;
}

export function unifiedDiff(a, b, {
  fromfile = '', tofile = '', fromfiledate = '', tofiledate = '', n = 3, lineterm = '\n',
} = {}) {
  const out = [];
  let started = false;
  const sm = new SequenceMatcher(null, a, b);
  for (const group of sm.getGroupedOpcodes(n)) {
    if (!started) {
      started = true;
      const fromdate = fromfiledate ? `\t${fromfiledate}` : '';
      const todate = tofiledate ? `\t${tofiledate}` : '';
      out.push(`--- ${fromfile}${fromdate}${lineterm}`);
      out.push(`+++ ${tofile}${todate}${lineterm}`);
    }
    const first = group[0], lastG = group[group.length - 1];
    const r1 = formatRangeUnified(first[1], lastG[2]);
    const r2 = formatRangeUnified(first[3], lastG[4]);
    out.push(`@@ -${r1} +${r2} @@${lineterm}`);
    for (const [tag, i1, i2, j1, j2] of group) {
      if (tag === 'equal') { for (const line of a.slice(i1, i2)) out.push(' ' + line); continue; }
      if (tag === 'replace' || tag === 'delete') for (const line of a.slice(i1, i2)) out.push('-' + line);
      if (tag === 'replace' || tag === 'insert') for (const line of b.slice(j1, j2)) out.push('+' + line);
    }
  }
  return out;
}

// ------------------------------------------------------- deepdiff gate
export function deepdiffDiffKey(oldValue, newValue) {
  if (oldValue === newValue) return null;
  if (!(oldValue.includes('\n') || newValue.includes('\n'))) return null;
  const d = unifiedDiff(splitlines(oldValue), splitlines(newValue), { lineterm: '' });
  if (d.length > 4) return d.join('\n');
  return null;
}

// Extra probes: (1) is autojunk observable for this program's input shape?
// (2) does len(diff)>4 ever gate anything off? (3) exotic content.
import { diffOf } from './diffprobe.mjs';
import { SequenceMatcher, splitlines, unifiedDiff, deepdiffDiffKey } from './difflib_ref.mjs';

function withAutojunk(a, flag) {
  const A = splitlines(a), B = splitlines(a + '2');
  const sm = new SequenceMatcher(null, A, B, flag);
  // replicate unifiedDiff but with our sm
  const out = [];
  let started = false;
  const fmt = (start, stop) => {
    let beg = start + 1; const len = stop - start;
    if (len === 1) return String(beg);
    if (!len) beg -= 1;
    return `${beg},${len}`;
  };
  for (const group of sm.getGroupedOpcodes(3)) {
    if (!started) { started = true; out.push('--- '); out.push('+++ '); }
    const f = group[0], l = group[group.length - 1];
    out.push(`@@ -${fmt(f[1], l[2])} +${fmt(f[3], l[4])} @@`);
    for (const [tag, i1, i2, j1, j2] of group) {
      if (tag === 'equal') { for (const x of A.slice(i1, i2)) out.push(' ' + x); continue; }
      if (tag !== 'insert') for (const x of A.slice(i1, i2)) out.push('-' + x);
      if (tag !== 'delete') for (const x of B.slice(j1, j2)) out.push('+' + x);
    }
  }
  return out;
}

const rep = (s, n) => Array.from({ length: n }, () => s);
const lines = (n, f) => Array.from({ length: n }, (_, i) => f(i + 1));

// --- (1) autojunk observability
const ajCases = [
  ['250 identical', rep('x', 250).join('\n')],
  ['250 identical +NL', rep('x', 250).join('\n') + '\n'],
  ['251 A then RARE', [...rep('A', 250), 'RARE'].join('\n')],
  ['400 mod2', lines(400, (i) => 'k' + (i % 2)).join('\n')],
  ['250 mod3', lines(250, (i) => 'm' + (i % 3)).join('\n')],
  ['300 mod7', lines(300, (i) => 'w' + (i % 7)).join('\n')],
  ['1000 identical', rep('z', 1000).join('\n')],
  ['205 A + UNIQ mid', [...rep('s', 100), 'UNIQ', ...rep('s', 104)].join('\n')],
  ['200 blank lines', rep('', 200).join('\n')],
  ['200 blank lines +NL', rep('', 200).join('\n') + '\n'],
];
console.log('=== autojunk on vs off (JS only) ===');
for (const [label, a] of ajCases) {
  const on = withAutojunk(a, true).join('\n');
  const off = withAutojunk(a, false).join('\n');
  console.log(`${on === off ? 'SAME' : 'DIFF'} ${label.padEnd(22)} on=${JSON.stringify(on.slice(0, 60))}`);
  if (on !== off) console.log(`     off=${JSON.stringify(off.slice(0, 120))}`);
}

// --- (2) len(diff) minimum: what is the smallest diff list length reachable?
console.log('\n=== diff list length distribution ===');
const lenCases = ['\n', 'a\n', '\n\n', '\r\n', '\n\r', 'x\n', '\nx', 'a\nb'];
for (const a of lenCases) {
  const d = unifiedDiff(splitlines(a), splitlines(a + '2'), { lineterm: '' });
  const exe = diffOf(a);
  console.log(`${JSON.stringify(a).padEnd(10)} len=${d.length}  exePresent=${exe.present}  match=${(exe.present ? exe.text : null) === (d.length > 4 ? d.join('\n') : null)}`);
}

// --- (3) exotic content against the executable
console.log('\n=== exotic content vs executable ===');
const exotic = [
  ['emoji lines', 'a\u{1F600}\nb\u{1F600}\nc'],
  ['astral tail', 'x\ny\n\u{10000}'],
  ['cjk', '中文\n日本語\nend'],
  ['combining', 'é\nà\nz'],
  ['nbsp lines', 'a \n b\nc'],
  ['zwsp', 'a​b\nc​d\ne'],
  ['long line 5000', 'y'.repeat(5000) + '\n' + 'z'.repeat(5000)],
